-- ----------------------------------------------------------------
-- 7. TRANSACCIONES  (estado final de cada operación; una por vehículo)
--    estado_transaccion: SOLICITAR | RESERVA | SENIADO | VENDIDO | CANCELADO
--    metodo_pago: EFECTIVO | TRANSFERENCIA | PLAN_AHORRO | CUOTA_BANCARIZADA
--    comision_calculada = 5% del precio_final, solo en las VENDIDO.
--    precio_final: el precio de venta del vehículo (no hay descuentos).
--    monto_entregado: el total si está VENDIDO; si no, lo pagado como reserva (hasta 50%) o seña (10%).
--    Los estados de los vehículos (sección 4) son consistentes con estas filas:
--      VENDIDO -> VENDIDO | SOLICITAR -> (sin cambio, vehiculo no retenido) | RESERVA/SENIADO -> RESERVADO | CANCELADO -> DISPONIBLE
-- ----------------------------------------------------------------
INSERT INTO transaccion (comision_calculada, created_at, estado_transaccion, metodo_pago, precio_final, monto_entregado, updated_at, cliente_id, vehiculo_id, vendedor_id, observaciones) VALUES (1125000, DATEADD('DAY', -60, CURRENT_DATE), 'VENDIDO', 'TRANSFERENCIA', 22500000, 22500000, DATEADD('DAY', -55, CURRENT_DATE), (SELECT id FROM usuario WHERE email = 'martin.perez@gmail.com'), (SELECT id_vehiculo FROM vehiculos WHERE patente = 'AB123CD'), (SELECT id FROM usuario WHERE email = 'carlos.garcia@agencia.com'), 'Venta Corolla XEI. Seña de 2.250.000 imputada.'),  (750000, DATEADD('DAY', -30, CURRENT_DATE), 'VENDIDO', 'EFECTIVO', 15000000, 15000000, DATEADD('DAY', -30, CURRENT_DATE), (SELECT id FROM usuario WHERE email = 'sofia.rodriguez@gmail.com'), (SELECT id_vehiculo FROM vehiculos WHERE patente = 'GH012IJ'), (SELECT id FROM usuario WHERE email = 'laura.fernandez@agencia.com'), 'Venta Focus S contado.'),  (1425000, DATEADD('DAY', -40, CURRENT_DATE), 'VENDIDO', 'CUOTA_BANCARIZADA', 28500000, 28500000, DATEADD('DAY', -35, CURRENT_DATE), (SELECT id FROM usuario WHERE email = 'sofia.rodriguez@gmail.com'), (SELECT id_vehiculo FROM vehiculos WHERE patente = 'KL678MN'), (SELECT id FROM usuario WHERE email = 'laura.fernandez@agencia.com'), 'Venta Golf Comfortline financiada. Seña de 2.850.000 imputada.'),  (0, DATEADD('DAY', -6, CURRENT_DATE), 'SENIADO', 'PLAN_AHORRO', 44000000, 4400000, DATEADD('DAY', -6, CURRENT_DATE), (SELECT id FROM usuario WHERE email = 'diego.gomez@gmail.com'), (SELECT id_vehiculo FROM vehiculos WHERE patente = 'CD456EF'), (SELECT id FROM usuario WHERE email = 'carlos.garcia@agencia.com'), 'Seña Hilux SRX de 4.400.000, saldo vía plan de ahorro.'),  (0, DATEADD('DAY', -3, CURRENT_DATE), 'RESERVA', 'TRANSFERENCIA', 35500000, 1000000, DATEADD('DAY', -3, CURRENT_DATE), (SELECT id FROM usuario WHERE email = 'valentina.martinez@gmail.com'), (SELECT id_vehiculo FROM vehiculos WHERE patente = 'OP234QR'), (SELECT id FROM usuario WHERE email = 'laura.fernandez@agencia.com'), 'Reserva Civic EX-L por 7 días.'),  (0, DATEADD('DAY', -25, CURRENT_DATE), 'CANCELADO', 'CUOTA_BANCARIZADA', 38000000, 3800000, DATEADD('DAY', -18, CURRENT_DATE), (SELECT id FROM usuario WHERE email = 'diego.gomez@gmail.com'), (SELECT id_vehiculo FROM vehiculos WHERE patente = 'IJ345KL'), (SELECT id FROM usuario WHERE email = 'carlos.garcia@agencia.com'), 'Cancelada: el cliente no obtuvo el crédito.');

